def update(index, value, bi_tree):
 while index < len(bi_tree):
  bi_tree[index] += value
  index += index & -index


def get_sum(index, bi_tree):
 ans = 0
 while index > 0:
  ans += bi_tree[index]
  index -= index & -index

 return ans


def get_range_sum(left, right, bi_tree):
 ans = get_sum(right, bi_tree) - get_sum(left - 1, bi_tree)
 return ans


