def get_Ls(Vs):
    L = []
    st = []
    for i, v in enumerate(Vs):
        while st and Vs[st[-1]] < v:
            st.pop()
        if st:
            L.append(st[-1] + 1)
        else:
            L.append(0)
        st.append(i)
    return L

def get_Ls_allow_ties(Vs):
    L = []
    st = []
    for i, v in enumerate(Vs):
        while st and Vs[st[-1]] <= v:
            st.pop()
        if st:
            L.append(st[-1] + 1)
        else:
            L.append(0)
        st.append(i)
    return L

def get_Rs(Vs):
    n = len(Vs)
    revVs = Vs[::-1]
    revRs = get_Ls(revVs)
    revRs.reverse()
    return [n - 1 - R for R in revRs]


def get_Rs_allow_ties(Vs):
    n = len(Vs)
    revVs = Vs[::-1]
