TIME=[1<<29]*(n+1)
TIME[1]=0

def shuku(x,y):
    return (x<<20)+y

Q=[]
ANS=[]

for k in range(n+1):
    NQ=[]

    if k<=1:
        heapq.heappush(Q,shuku(0,1))

    if k%2==0:
        while Q:
            #print(Q)
            x=heapq.heappop(Q)
            time=x>>20
            town=x-(time<<20)

            #print(x,time,town)

            if TIME[town]<time:
                continue

            for to in E[town]:
                if TIME[to]>time+1:
                    TIME[to]=time+1
                    heapq.heappush(Q,shuku(TIME[to],to))
                    heapq.heappush(NQ,shuku(TIME[to],to))

    else:
        while Q:
            x=heapq.heappop(Q)
            time=x>>20
            town=x-(time<<20)

            #print(x,time,town)

            if TIME[town]<time:
                continue

            for to in E2[town]:
                if TIME[to]>time+1:
                    TIME[to]=time+1
                    heapq.heappush(Q,shuku(TIME[to],to))
                    heapq.heappush(NQ,shuku(TIME[to],to))

    #print(k,TIME)

    Q=NQ
    ANS.append(TIME[n])

